"""HST Draw's ribbon (hst-ribbon-draw.patch, generated by scripts/patches/generate-draw-ribbon.py, and
hst-ribbon-draw-engine.patch). Reads the patches only; the generator itself needs a patched tree."""
import importlib.util
import os
import re
import unittest

from _paths import ROOT

PATCHES = os.path.join(ROOT, "patches", "libreoffice")
spec = importlib.util.spec_from_file_location("generate_draw_ribbon", os.path.join(ROOT, "scripts/patches/generate-draw-ribbon.py"))
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)


def read(name):
    with open(os.path.join(PATCHES, name), encoding="utf-8") as handle:
        return handle.read()


def section(text, path):
    """The hunks of one file of a patch."""
    start = text.index(f"+++ b/{path}\n")
    end = text.find("\n--- a/", start)
    return text[start:end if end >= 0 else len(text)]


def added(text):
    return "\n".join(line[1:] for line in text.splitlines() if line.startswith("+") and not line.startswith("+++"))


class DrawRibbonPatch(unittest.TestCase):
    patch = read("hst-ribbon-draw.patch")

    def test_new_tabs_and_their_strings(self):
        ui = added(section(self.patch, gen.DRAW_UI))
        for label_id in ("ArrangeLabel", "ExportLabel"):
            self.assertIn(f'id="{label_id}"', ui)
        po = section(self.patch, gen.VI_PO)
        for context, msgid, msgstr in gen.STRINGS:
            self.assertIn(f'msgctxt "{context}"\n+msgid "{msgid}"\n+msgstr "{msgstr}"', po)
            self.assertIn(f'context="{context}">{msgid}<', ui)

    def test_no_slide_only_command_is_added(self):
        ui = added(section(self.patch, gen.DRAW_UI))
        commands = set(re.findall(r'"action-name">([^<]+)<', ui))
        self.assertFalse(commands & (gen.DROP_COMMANDS | set(gen.SWAP_COMMANDS)), commands & gen.DROP_COMMANDS)
        self.assertIn(gen.OPEN_IN_HST_PDF, commands)
        self.assertIn(".uno:LeftPaneDraw", commands)

    def test_ribbon_is_the_active_mode_without_menu_bar(self):
        xcu = section(self.patch, gen.TOOLBAR_MODE)
        self.assertIn("+        <value>notebookbar.ui</value>", xcu)
        self.assertIn("-            <value>true</value>\n+            <value>false</value>", xcu)

    def test_unlabelled_buttons_are_suppressed(self):
        suppr = section(self.patch, gen.DRAW_SUPPR)
        self.assertIn("sd/uiconfig/sdraw/ui/notebookbar.ui://GtkToolButton[@id='btnExportToPDF'] button-no-label", suppr)


class DrawEnginePatch(unittest.TestCase):
    patch = read("hst-ribbon-draw-engine.patch")

    def test_banner_search_and_keytips_attach_to_draw(self):
        self.assertIn('+                    && rFile.indexOf("/simpress/") < 0 && rFile.indexOf("/sdraw/") < 0))', self.patch)

    def test_backstage_knows_draw(self):
        body = added(self.patch)
        self.assertIn("BackstageApp::Draw", body)
        self.assertIn('u"draw8"_ustr, STR_HST_BS_FMT_ODG', body)
        self.assertIn('msgstr "Bản vẽ trống"', body)
        self.assertIn('msgstr "Bản vẽ ODF (.odg)"', body)


if __name__ == "__main__":
    unittest.main()
